// LTO dead-code elimination on a toy call graph
const graph={"main": ["core"], "core": [], "old": []};
const entry="main";
const live=new Set([entry]),q=[entry];
while(q.length){const f=q.pop();for(const g of (graph[f]||[]))if(!live.has(g)){live.add(g);q.push(g);}}
console.log('live: '+[...live].join(', '));
console.log('eliminated: '+(Object.keys(graph).filter(f=>!live.has(f)).join(', ')||'none'));

